INSERT INTO question_bank (question_text, options, correct_option, topic, difficulty, is_active) VALUES
('Which key uniquely identifies a record in a table and is chosen by the database designer as the main identifier?', '["Primary key", "Foreign key", "Candidate key", "Super key"]'::jsonb, 0, 'dbms', 'easy', true),
('A key that references the primary key of another table is called a:', '["Candidate key", "Super key", "Foreign key", "Composite key"]'::jsonb, 2, 'dbms', 'easy', true),
('Which of the following is a minimal super key?', '["Super key", "Candidate key", "Foreign key", "Composite key"]'::jsonb, 1, 'dbms', 'easy', true),
('A set of one or more attributes that can uniquely identify a tuple is called a:', '["Null key", "Weak key", "Partial key", "Super key"]'::jsonb, 3, 'dbms', 'easy', true),
('Candidate keys that are not chosen as the primary key are called:', '["Foreign keys", "Composite keys", "Super keys", "Alternate keys"]'::jsonb, 3, 'dbms', 'easy', true),
('In an ER diagram, an entity is represented by a:', '["Ellipse", "Rectangle", "Diamond", "Line"]'::jsonb, 1, 'dbms', 'easy', true),
('In an ER diagram, a relationship is represented by a:', '["Rectangle", "Ellipse", "Diamond", "Triangle"]'::jsonb, 2, 'dbms', 'easy', true),
('In an ER diagram, an attribute is represented by a:', '["Ellipse", "Rectangle", "Diamond", "Circle-only shape reserved for keys"]'::jsonb, 0, 'dbms', 'easy', true),
('A weak entity is an entity that:', '["Has no attributes at all", "Cannot be uniquely identified by its own attributes alone", "Cannot participate in any relationship", "Always has a composite primary key"]'::jsonb, 1, 'dbms', 'easy', true),
('The attribute that uniquely identifies a weak entity within the scope of its owner entity is called a:', '["Primary key", "Foreign key", "Candidate key", "Partial key (discriminator)"]'::jsonb, 3, 'dbms', 'easy', true),
('Which of the following can legally contain NULL values in a relational table?', '["A foreign key, when the referencing relationship is optional", "A primary key", "A candidate key chosen as the primary key", "None of these can ever be NULL"]'::jsonb, 0, 'dbms', 'medium', true),
('A relation has attributes A, B, C, D where AB is the only candidate key. Which attribute set is a super key but NOT a candidate key?', '["AB", "A", "ABC", "B"]'::jsonb, 2, 'dbms', 'medium', true),
('In ER modeling, a relationship where each entity in set A relates to at most one entity in set B, and vice versa, is called:', '["One-to-one", "One-to-many", "Many-to-one", "Many-to-many"]'::jsonb, 0, 'dbms', 'medium', true),
('Total participation of an entity in a relationship is represented in ER diagrams using a:', '["Single line", "Dashed line", "Double line connecting the entity to the relationship", "Dotted rectangle"]'::jsonb, 2, 'dbms', 'medium', true),
('An attribute whose value can be derived from other attributes is called a:', '["Composite attribute", "Derived attribute", "Multivalued attribute", "Key attribute"]'::jsonb, 1, 'dbms', 'medium', true),
('An attribute that can take multiple values simultaneously for a single entity instance is called a:', '["Composite attribute", "Derived attribute", "Simple attribute", "Multivalued attribute"]'::jsonb, 3, 'dbms', 'medium', true),
('Which of the following best defines a foreign key constraint?', '["It enforces uniqueness of values within a single table", "It enforces a domain constraint on a column", "It automatically speeds up query execution", "It enforces referential integrity between two tables"]'::jsonb, 3, 'dbms', 'medium', true),
('Converting a many-to-many relationship between two entities into the relational model typically requires:', '["Adding a foreign key to only one of the entity tables", "Creating a separate junction (bridge) table containing the primary keys of both entities as foreign keys", "Merging both entities into a single table", "Adding a composite attribute to one entity"]'::jsonb, 1, 'dbms', 'medium', true),
('In an Enhanced ER (EER) diagram, specialization/generalization is represented using a:', '["Diamond", "Rectangle", "Triangle (labeled ISA)", "Ellipse"]'::jsonb, 2, 'dbms', 'medium', true),
('Relation R(A,B,C,D) has the single functional dependency A -> B,C,D. What is the candidate key of R?', '["A", "B", "C", "AB"]'::jsonb, 0, 'dbms', 'medium', true),
('Relation R(A,B,C,D) has exactly two candidate keys, AB and CD, with no other candidate keys. Which statement is true?', '["A alone is a candidate key of R", "No proper subset of AB or CD can determine all other attributes of R", "ABCD is the only super key of R", "C alone functionally determines D"]'::jsonb, 1, 'dbms', 'hard', true),
('A relation has exactly three candidate keys: (A), (B,C), and (D). How many distinct prime attributes does this relation have?', '["3", "1", "2", "4"]'::jsonb, 3, 'dbms', 'hard', true),
('In ER modeling, which (min,max) participation/cardinality pair indicates that entity B participates in relationship R with total participation and a maximum of exactly one relationship instance?', '["(1,1)", "(0,1)", "(0,N)", "(1,N)"]'::jsonb, 0, 'dbms', 'hard', true),
('Given entities EMPLOYEE and DEPARTMENT related by a 1:N relationship ''works_in'' (one department has many employees), where should the foreign key be placed when mapping this to a relational schema?', '["In the DEPARTMENT table, referencing the EMPLOYEE table", "In a new junction table linking both", "In the EMPLOYEE table, referencing the DEPARTMENT table", "In both tables simultaneously"]'::jsonb, 2, 'dbms', 'hard', true),
('Relation R(A,B,C,D,E) has FDs A->B, BC->D, and D->E. Which of the following is a candidate key of R?', '["AC", "AB", "BC", "AD"]'::jsonb, 0, 'dbms', 'hard', true);
INSERT INTO question_bank (question_text, options, correct_option, topic, difficulty, is_active) VALUES
('A relation is in First Normal Form (1NF) if all attribute values are:', '["Unique across the table", "Numeric", "Atomic (indivisible)", "Foreign keys"]'::jsonb, 2, 'dbms', 'easy', true),
('Which normal form requires that there be no partial dependency of any non-prime attribute on a candidate key?', '["1NF", "2NF", "3NF", "BCNF"]'::jsonb, 1, 'dbms', 'easy', true),
('Which normal form requires that there be no transitive dependency of non-prime attributes on the primary key?', '["2NF", "1NF", "BCNF", "3NF"]'::jsonb, 3, 'dbms', 'easy', true),
('A relation is in BCNF if, for every non-trivial functional dependency X -> Y, X must be a:', '["Candidate key only, never a super key", "Foreign key", "Prime attribute", "Super key"]'::jsonb, 3, 'dbms', 'easy', true),
('The process of decomposing a relation to remove redundancy and reduce anomalies is called:', '["Denormalization", "Normalization", "Indexing", "Serialization"]'::jsonb, 1, 'dbms', 'easy', true),
('A relation containing a repeating group of attributes (e.g., a multivalued column storing a list) violates:', '["2NF", "3NF", "1NF", "BCNF"]'::jsonb, 2, 'dbms', 'easy', true),
('A partial dependency can occur only when the primary key of a relation is:', '["Composite (consists of more than one attribute)", "Simple (a single attribute)", "Non-existent", "A foreign key"]'::jsonb, 0, 'dbms', 'easy', true),
('A transitive dependency exists when a non-prime attribute depends on another non-prime attribute, which in turn depends on the:', '["Foreign key", "Candidate key", "An unrelated non-prime attribute", "A null value"]'::jsonb, 1, 'dbms', 'easy', true),
('Every relation that is in BCNF is also guaranteed to be in:', '["4NF", "5NF", "2NF, but never 3NF", "3NF"]'::jsonb, 3, 'dbms', 'easy', true),
('Which normal form deals specifically with eliminating multivalued dependencies?', '["4NF", "3NF", "BCNF", "2NF"]'::jsonb, 0, 'dbms', 'easy', true),
('Relation STUDENT(RollNo, Course, Instructor) has the FD Course -> Instructor, with primary key (RollNo, Course). This relation violates:', '["1NF", "BCNF only, not 2NF", "2NF", "No normal form; it is fully normalized"]'::jsonb, 2, 'dbms', 'medium', true),
('Relation EMP(EmpID, EmpName, DeptID, DeptName) has FDs EmpID -> EmpName, DeptID and DeptID -> DeptName, with primary key EmpID. This relation violates:', '["3NF", "2NF", "1NF", "BCNF only, not 3NF"]'::jsonb, 0, 'dbms', 'medium', true),
('Which of the following statements about 2NF is true?', '["2NF requires that there be no transitive dependency", "2NF requires all attributes to be atomic", "A relation whose primary key is a single attribute is automatically in 2NF if it is already in 1NF", "2NF is a stronger requirement than BCNF"]'::jsonb, 2, 'dbms', 'medium', true),
('Relation R(A,B,C) has the FD B -> C, where B is not a super key of R. This relation violates:', '["1NF", "BCNF", "2NF", "None of the normal forms are violated"]'::jsonb, 1, 'dbms', 'medium', true),
('Decomposing a relation into BCNF can sometimes result in the loss of:', '["Atomicity of attribute values", "The lossless-join property, which always fails for BCNF decompositions", "All candidate keys", "A functional dependency (dependency preservation)"]'::jsonb, 3, 'dbms', 'medium', true),
('Which of the following is true regarding lossless-join decomposition?', '["The decomposed relations must share no common attributes", "The decomposed relations must always end up in BCNF", "Lossless-join decomposition is impossible when decomposing into BCNF", "The natural join of the decomposed relations must reproduce exactly the original relation"]'::jsonb, 3, 'dbms', 'medium', true),
('Relation R(A,B,C,D) has FDs A->B, A->C, A->D, and is in 1NF with A as the (single-attribute) primary key. What is required to bring it to 2NF?', '["Decompose into R1(A,B) and R2(A,C,D)", "Nothing further; it is already in 2NF", "Remove attribute D entirely", "Split it into four separate single-attribute relations"]'::jsonb, 1, 'dbms', 'medium', true),
('Which anomaly occurs when deleting a row unintentionally removes information about an unrelated entity, due to unnormalized/redundant data?', '["Insertion anomaly", "Update anomaly", "Deletion anomaly", "Referential anomaly"]'::jsonb, 2, 'dbms', 'medium', true),
('Which anomaly occurs when the same fact is duplicated across multiple rows, risking inconsistency if not all copies are updated together?', '["Update anomaly", "Insertion anomaly", "Deletion anomaly", "Domain anomaly"]'::jsonb, 0, 'dbms', 'medium', true),
('Which anomaly occurs when you cannot insert information about one entity because the value of another, unrelated attribute is not yet known?', '["Deletion anomaly", "Insertion anomaly", "Update anomaly", "Consistency anomaly"]'::jsonb, 1, 'dbms', 'medium', true),
('Relation R(A,B,C,D,E) has FDs AB->C, C->D, D->E, with candidate key AB. Which of the following functional dependencies directly represents a transitive dependency (a non-prime attribute determining another non-prime attribute)?', '["AB -> C", "AB -> D", "AB -> E", "C -> D"]'::jsonb, 3, 'dbms', 'hard', true),
('Relation R(A,B,C,D) has FDs A->B, A->C, C->D, with A as the single-attribute primary key. Which normal form is violated (the lowest one not satisfied)?', '["3NF, because C->D is a transitive dependency (C is non-prime)", "2NF, because of a partial dependency", "1NF, because of a repeating group", "BCNF only; 3NF is satisfied"]'::jsonb, 0, 'dbms', 'hard', true),
('Relation R(A,B,C) has FDs A->B and B->C, with A as the only candidate key. Which BCNF decomposition is correct and lossless?', '["R1(A,C) and R2(B,C)", "R1(A,B,C), left undecomposed", "R1(A,B) and R2(B,C)", "R1(A) and R2(B,C)"]'::jsonb, 2, 'dbms', 'hard', true),
('Relation R(A,B,C,D) has FDs AB->CD and C->B. Which of the following is TRUE?', '["R violates BCNF because C->B holds but C is not a super key", "R is already in BCNF", "C->B causes no BCNF violation because B is a prime attribute", "AB->CD violates BCNF"]'::jsonb, 0, 'dbms', 'hard', true),
('If a functional dependency X -> Y holds where X is not a candidate key but Y is a prime attribute (part of some other candidate key), which statement is correct?', '["The relation always violates 3NF in this situation", "The relation always satisfies BCNF in this situation", "The relation may satisfy 3NF (due to its prime-attribute exception) while still violating BCNF", "X must necessarily be a foreign key"]'::jsonb, 2, 'dbms', 'hard', true);
INSERT INTO question_bank (question_text, options, correct_option, topic, difficulty, is_active) VALUES
('Which SQL clause is used to filter rows AFTER grouping has been performed?', '["WHERE", "HAVING", "GROUP BY", "ORDER BY"]'::jsonb, 1, 'dbms', 'easy', true),
('Which SQL clause is used to filter rows BEFORE any grouping is performed?', '["HAVING", "GROUP BY", "ORDER BY", "WHERE"]'::jsonb, 3, 'dbms', 'easy', true),
('Which SQL keyword is used to sort the result set of a query?', '["GROUP BY", "SORT BY", "ARRANGE BY", "ORDER BY"]'::jsonb, 3, 'dbms', 'easy', true),
('Which SQL join returns only the rows that have matching values in both joined tables?', '["LEFT JOIN", "INNER JOIN", "RIGHT JOIN", "FULL OUTER JOIN"]'::jsonb, 1, 'dbms', 'easy', true),
('Which SQL join returns all rows from the left table and matched rows from the right table, filling unmatched right-side columns with NULL?', '["INNER JOIN", "RIGHT OUTER JOIN", "LEFT OUTER JOIN", "CROSS JOIN"]'::jsonb, 2, 'dbms', 'easy', true),
('Which SQL join returns all rows from both tables, with NULLs where there is no match on either side?', '["FULL OUTER JOIN", "INNER JOIN", "LEFT JOIN", "RIGHT JOIN"]'::jsonb, 0, 'dbms', 'easy', true),
('Which SQL keyword removes duplicate rows from a query''s result set?', '["UNIQUE", "DISTINCT", "DISTINCT ROW", "FILTER"]'::jsonb, 1, 'dbms', 'easy', true),
('Which aggregate function returns the number of rows in a result set?', '["SUM", "TOTAL", "NUM", "COUNT"]'::jsonb, 3, 'dbms', 'easy', true),
('Which SQL keyword combines the result sets of two SELECT queries and automatically removes duplicate rows from the combined result?', '["UNION", "UNION ALL", "JOIN", "INTERSECT"]'::jsonb, 0, 'dbms', 'easy', true),
('Which SQL command is used to retrieve data from a database table?', '["GET", "FETCH", "SELECT", "RETRIEVE"]'::jsonb, 2, 'dbms', 'easy', true),
('A CROSS JOIN between a table with 5 rows and a table with 3 rows (with no filtering) produces how many rows in the result?', '["15", "8", "3", "5"]'::jsonb, 0, 'dbms', 'medium', true),
('Which query correctly returns department IDs having more than 5 employees, using GROUP BY and HAVING?', '["SELECT dept_id, COUNT(*) FROM employees WHERE COUNT(*) > 5 GROUP BY dept_id", "SELECT dept_id FROM employees HAVING COUNT(*) > 5", "SELECT dept_id, COUNT(*) FROM employees GROUP BY dept_id HAVING COUNT(*) > 5", "SELECT dept_id, COUNT(*) FROM employees GROUP BY dept_id WHERE COUNT(*) > 5"]'::jsonb, 2, 'dbms', 'medium', true),
('In SQL, a subquery that references a column from its enclosing outer query is called a:', '["Nested subquery", "Correlated subquery", "Scalar subquery", "Derived table"]'::jsonb, 1, 'dbms', 'medium', true),
('Which operator is used with a subquery to check whether a value matches any single value returned by that subquery?', '["EXISTS only", "ALL", "LIKE", "IN"]'::jsonb, 3, 'dbms', 'medium', true),
('The EXISTS operator applied to a subquery returns TRUE if:', '["The subquery returns exactly one row", "The subquery returns a NULL value", "The subquery returns zero rows", "The subquery returns at least one row"]'::jsonb, 3, 'dbms', 'medium', true),
('What does the query ''SELECT dept_id, AVG(salary) FROM employees GROUP BY dept_id'' return?', '["The average salary of all employees combined", "The average salary for each department", "The maximum salary per department", "The total salary per department"]'::jsonb, 1, 'dbms', 'medium', true),
('Which query correctly finds employees who earn more than the average salary of all employees?', '["SELECT * FROM employees WHERE salary > AVG(salary)", "SELECT * FROM employees GROUP BY salary HAVING salary > AVG(salary)", "SELECT * FROM employees WHERE salary > (SELECT AVG(salary) FROM employees)", "SELECT * FROM employees WHERE salary > ALL(salary)"]'::jsonb, 2, 'dbms', 'medium', true),
('A self-join is used to:', '["Join a table with itself", "Join a table with a view", "Join two completely unrelated tables", "Join a table only with a subquery"]'::jsonb, 0, 'dbms', 'medium', true),
('Among GROUP BY, HAVING, and ORDER BY, in what clause order must they appear in a single SELECT statement?', '["HAVING, then GROUP BY, then ORDER BY", "GROUP BY, then HAVING, then ORDER BY", "ORDER BY, then GROUP BY, then HAVING", "GROUP BY, then ORDER BY, then HAVING"]'::jsonb, 1, 'dbms', 'medium', true),
('What happens when you compute ''SELECT COUNT(column_name) FROM table'' and column_name contains NULL values in some rows?', '["The NULL values are counted as zero each", "The presence of NULL values causes an error", "The NULL values are each counted as one", "The NULL values are excluded from the count"]'::jsonb, 3, 'dbms', 'medium', true),
('Given table A(id) with rows (1,2,3) and table B(id) with rows (2,3,4), what does ''SELECT id FROM A LEFT JOIN B ON A.id = B.id WHERE B.id IS NULL'' return?', '["1", "4", "2 and 3", "An empty result set"]'::jsonb, 0, 'dbms', 'hard', true),
('In a query that uses GROUP BY along with an aggregate function but no HAVING clause, which kind of column in the SELECT list is invalid under standard SQL?', '["A column that is listed in GROUP BY", "A column wrapped in COUNT()", "A column that is neither listed in GROUP BY nor wrapped in an aggregate function", "A column wrapped in SUM()"]'::jsonb, 2, 'dbms', 'hard', true),
('What is the key functional difference between UNION and UNION ALL in SQL?', '["UNION removes duplicate rows from the combined result while UNION ALL keeps them", "UNION always executes faster than UNION ALL", "UNION ALL requires identical column names while UNION does not", "UNION works only on numeric columns"]'::jsonb, 0, 'dbms', 'hard', true),
('In a correlated NOT EXISTS subquery used to find customers with no orders, how does a NULL value in the join column of the subquery''s correlation condition typically affect the outcome for that row?', '["It always makes NOT EXISTS evaluate to TRUE for that row", "It always makes NOT EXISTS evaluate to FALSE for that row", "Its evaluation depends on three-valued NULL comparison logic and may not behave as intuitively expected", "It always causes a SQL syntax error"]'::jsonb, 2, 'dbms', 'hard', true),
('Consider: SELECT dept_id FROM employees GROUP BY dept_id HAVING COUNT(*) = (SELECT MAX(cnt) FROM (SELECT COUNT(*) cnt FROM employees GROUP BY dept_id) t). What does this query return?', '["The department with the smallest number of employees", "The department(s) with the largest number of employees", "All departments in the table", "The average department size"]'::jsonb, 1, 'dbms', 'hard', true);
INSERT INTO question_bank (question_text, options, correct_option, topic, difficulty, is_active) VALUES
('Which relational algebra operation selects rows from a relation that satisfy a given condition?', '["Projection (pi)", "Union", "Join", "Selection (sigma)"]'::jsonb, 3, 'dbms', 'easy', true),
('Which relational algebra operation selects specific columns (attributes) from a relation?', '["Selection (sigma)", "Cartesian Product", "Rename", "Projection (pi)"]'::jsonb, 3, 'dbms', 'easy', true),
('The symbol sigma (σ) in relational algebra represents which operation?', '["Projection", "Selection", "Union", "Intersection"]'::jsonb, 1, 'dbms', 'easy', true),
('The symbol pi (π) in relational algebra represents which operation?', '["Selection", "Set Difference", "Projection", "Division"]'::jsonb, 2, 'dbms', 'easy', true),
('Which relational algebra operation combines tuples from two relations that satisfy a specified join condition?', '["Join", "Union", "Set Difference", "Projection"]'::jsonb, 0, 'dbms', 'easy', true),
('The Cartesian product of relation R (with 4 tuples) and relation S (with 6 tuples) produces how many tuples?', '["10", "24", "6", "4"]'::jsonb, 1, 'dbms', 'easy', true),
('Which relational algebra operator is used to rename a relation or its attributes?', '["Select (sigma)", "Project (pi)", "Assign", "Rename (rho)"]'::jsonb, 3, 'dbms', 'easy', true),
('For the Union operation (R union S) to be valid in relational algebra, R and S must be:', '["Union-compatible (same number of attributes with matching domains)", "Identical relations", "Disjoint relations with no common tuples", "Joined on a common key"]'::jsonb, 0, 'dbms', 'easy', true),
('Which relational algebra operation returns the tuples present in R but not present in S?', '["Union (R union S)", "Intersection (R intersect S)", "Set Difference (R minus S)", "Cartesian Product"]'::jsonb, 2, 'dbms', 'easy', true),
('Which relational algebra operation returns only the tuples that are common to both R and S?', '["Intersection", "Union", "Set Difference", "Cartesian Product"]'::jsonb, 0, 'dbms', 'easy', true),
('The natural join of two relations R and S is equivalent to which combination of basic relational algebra operations?', '["Only a Cartesian product", "Only a Union", "A selection on their Cartesian product (equating common attributes), followed by a projection removing duplicate columns", "A set difference followed by a projection"]'::jsonb, 2, 'dbms', 'medium', true),
('Relational algebra is considered a _______ query language.', '["Non-procedural (declarative)", "Procedural", "Object-oriented", "Purely functional"]'::jsonb, 1, 'dbms', 'medium', true),
('Relational calculus, unlike relational algebra, is a _______ query language.', '["Procedural", "Imperative", "Sequential", "Non-procedural (declarative)"]'::jsonb, 3, 'dbms', 'medium', true),
('The division operator in relational algebra (R divided-by S) is typically used to answer queries of the type:', '["Find entities in R related to ANY entity in S", "Find entities common to both R and S", "Find entities present in R but not in S", "Find entities in R that are related to ALL entities in S"]'::jsonb, 3, 'dbms', 'medium', true),
('Which SQL construct corresponds most closely to relational algebra''s Selection (sigma) operation?', '["The SELECT column list", "The WHERE clause", "The GROUP BY clause", "The ORDER BY clause"]'::jsonb, 1, 'dbms', 'medium', true),
('Which SQL construct corresponds most closely to relational algebra''s Projection (pi) operation?', '["The WHERE clause", "The FROM clause", "The SELECT column list", "The HAVING clause"]'::jsonb, 2, 'dbms', 'medium', true),
('In relational algebra, an equi-join is a join whose join condition uses which comparison operator?', '["Equality (=)", "Inequality (<>)", "Less than (<)", "Greater than (>)"]'::jsonb, 0, 'dbms', 'medium', true),
('A theta join in relational algebra is a join that uses:', '["Only the equality operator", "Any comparison operator (theta) in its join condition", "No condition at all, i.e. a plain Cartesian product", "Only the natural-join condition"]'::jsonb, 1, 'dbms', 'medium', true),
('The outer join in relational algebra preserves dangling (unmatched) tuples by padding their missing attribute values with:', '["Zero", "An empty string", "The domain''s default value", "NULL"]'::jsonb, 3, 'dbms', 'medium', true),
('Which of the following is NOT one of the fundamental (primitive) operations of relational algebra?', '["Join", "Selection", "Projection", "Union"]'::jsonb, 0, 'dbms', 'medium', true),
('Given relations R(A,B) and S(B,C), the expression pi_A,C(R join S) is equivalent to which SQL query?', '["SELECT R.A, S.C FROM R, S", "SELECT R.A, S.C FROM R JOIN S ON R.A = S.C", "SELECT R.A, S.C FROM R JOIN S ON R.B = S.B", "SELECT * FROM R, S"]'::jsonb, 2, 'dbms', 'hard', true),
('For relations R(A,B,C) and S(A,B), which expression correctly derives R divided-by S (division) using only projection, selection, Cartesian product, and set difference?', '["pi_C(R) minus pi_C( (pi_C(R) times S) minus R )", "pi_C(R) intersect S", "pi_A,B(R) minus S", "pi_C(R) union S"]'::jsonb, 0, 'dbms', 'hard', true),
('Given Depositor(cust, acct) and Account(acct, branch), which relational algebra expression finds customers who have accounts at ALL branches?', '["pi_cust(Depositor) intersect pi_branch(Account)", "pi_cust(Depositor join Account)", "pi_cust,branch(Depositor join Account) divided-by pi_branch(Account)", "Depositor union Account"]'::jsonb, 2, 'dbms', 'hard', true),
('If relation R has degree 3 and relation S has degree 5, what is the degree of R times S (Cartesian product)?', '["15", "8", "3", "5"]'::jsonb, 1, 'dbms', 'hard', true),
('Which statement correctly distinguishes relational algebra from SQL?', '["Relational algebra and SQL are identical in both expressive power and syntax", "SQL is procedural while relational algebra is purely declarative", "Relational algebra cannot express join operations at all", "Relational algebra specifies HOW to retrieve data (procedural, order of operations matters), while SQL is primarily declarative (WHAT to retrieve)"]'::jsonb, 3, 'dbms', 'hard', true);
INSERT INTO question_bank (question_text, options, correct_option, topic, difficulty, is_active) VALUES
('ACID stands for Atomicity, Consistency, Isolation, and:', '["Dependency", "Deadlock-freedom", "Data integrity", "Durability"]'::jsonb, 3, 'dbms', 'easy', true),
('Which ACID property ensures that a transaction is treated as a single, indivisible unit that either fully completes or has no effect at all?', '["Consistency", "Atomicity", "Isolation", "Durability"]'::jsonb, 1, 'dbms', 'easy', true),
('Which ACID property ensures that once a transaction is committed, its changes persist even if the system subsequently fails?', '["Atomicity", "Consistency", "Durability", "Isolation"]'::jsonb, 2, 'dbms', 'easy', true),
('Which ACID property ensures that concurrently executing transactions do not interfere with each other''s intermediate (uncommitted) states?', '["Isolation", "Atomicity", "Consistency", "Durability"]'::jsonb, 0, 'dbms', 'easy', true),
('Which ACID property ensures that a transaction takes the database from one valid consistent state to another valid consistent state?', '["Atomicity", "Consistency", "Isolation", "Durability"]'::jsonb, 1, 'dbms', 'easy', true),
('Which SQL command permanently saves the changes made by the current transaction?', '["SAVE", "ROLLBACK", "FLUSH", "COMMIT"]'::jsonb, 3, 'dbms', 'easy', true),
('Which SQL command undoes the changes made by an uncommitted transaction?', '["ROLLBACK", "COMMIT", "UNDO", "CANCEL"]'::jsonb, 0, 'dbms', 'easy', true),
('A transaction that has not yet committed or aborted, and is currently performing operations, is in which state?', '["Committed", "Failed", "Active", "Terminated"]'::jsonb, 2, 'dbms', 'easy', true),
('The state of a transaction right after it has executed its final operation, but before it is fully committed, is called:', '["Partially committed", "Active", "Failed", "Aborted"]'::jsonb, 0, 'dbms', 'easy', true),
('A SAVEPOINT within a transaction allows you to:', '["Permanently commit part of the transaction", "Lock a specific row exclusively", "Roll back to a specific point within the transaction without undoing the entire transaction", "Start a brand-new transaction"]'::jsonb, 2, 'dbms', 'easy', true),
('If a transaction fails partway through updating the database, which ACID property ensures that its partial updates are undone?', '["Isolation", "Atomicity", "Durability", "Consistency"]'::jsonb, 1, 'dbms', 'medium', true),
('A schedule is called ''serializable'' if it produces a result equivalent to some:', '["Random interleaving of transactions", "Fully parallel execution with no ordering", "A schedule that always deadlocks", "Serial execution of the same set of transactions"]'::jsonb, 3, 'dbms', 'medium', true),
('Which type of schedule allows operations of different transactions to be interleaved during execution?', '["A serial schedule", "A cascadeless schedule, exclusively", "A recoverable schedule, exclusively", "A concurrent (non-serial) schedule"]'::jsonb, 3, 'dbms', 'medium', true),
('A recoverable schedule ensures that:', '["All transactions execute strictly one after another", "A transaction commits only after every transaction whose changes it read has already committed", "Deadlocks can never occur", "Locks are never released until the database shuts down"]'::jsonb, 1, 'dbms', 'medium', true),
('A cascadeless schedule specifically prevents which phenomenon?', '["Deadlocks between transactions", "Starvation of a waiting transaction", "Cascading rollbacks, where one transaction''s abort forces the rollback of others that read its uncommitted data", "Dirty pages in the buffer cache"]'::jsonb, 2, 'dbms', 'medium', true),
('The ''dirty read'' problem occurs when a transaction reads:', '["Data written by another transaction that has not yet committed", "Data that does not exist in the table", "Data from a transaction that has already committed", "Corrupted data from a disk failure"]'::jsonb, 0, 'dbms', 'medium', true),
('The ''lost update'' problem occurs when:', '["A transaction reads uncommitted data from another transaction", "Two transactions read the same data and one transaction''s update is overwritten by the other''s without being accounted for", "A transaction is unable to locate the requested data", "The database crashes in the middle of a transaction"]'::jsonb, 1, 'dbms', 'medium', true),
('Which transaction isolation level permits dirty reads to occur?', '["READ COMMITTED", "REPEATABLE READ", "SERIALIZABLE", "READ UNCOMMITTED"]'::jsonb, 3, 'dbms', 'medium', true),
('Which transaction isolation level provides the strictest isolation, preventing dirty reads, non-repeatable reads, and phantom reads?', '["SERIALIZABLE", "READ COMMITTED", "READ UNCOMMITTED", "REPEATABLE READ"]'::jsonb, 0, 'dbms', 'medium', true),
('A ''non-repeatable read'' occurs when:', '["A transaction is unable to read any data at all", "The same query returns rows in a different order on repeated execution", "A transaction reads the same row twice and gets different values because another transaction committed a modification in between", "A transaction reads a row that was deleted before the transaction even started"]'::jsonb, 2, 'dbms', 'medium', true),
('Which of the following is generally true about the REPEATABLE READ isolation level in most database implementations?', '["It prevents dirty reads and non-repeatable reads but may still allow phantom reads", "It prevents all anomalies including phantom reads, identical to SERIALIZABLE", "It allows dirty reads but prevents non-repeatable reads", "It is the weakest of the standard isolation levels"]'::jsonb, 0, 'dbms', 'hard', true),
('The write-ahead logging (WAL) protocol used for recovery requires that:', '["Data modifications be written to disk before their log records", "Transaction logs are optional as long as durability is achieved another way", "The log record of an update be written to stable storage before the corresponding data modification is written to the database", "Only committed transactions ever generate log records"]'::jsonb, 2, 'dbms', 'hard', true),
('A ''phantom read'' anomaly occurs when:', '["A transaction reads a row that has been deleted", "A transaction re-executes a range query and finds new rows inserted (and committed) by another transaction that were not present before", "A transaction reads the same single row twice under two different isolation levels", "A transaction encounters an unexpected NULL value"]'::jsonb, 1, 'dbms', 'hard', true),
('Suppose transaction T1 reads a value written by transaction T2 before T2 has committed, and T1 then commits before T2 does. Under strict two-phase locking, this exact scenario:', '["Is guaranteed to happen in every schedule that uses strict 2PL", "Is required in order to guarantee serializability", "Only affects durability, not isolation, under strict 2PL", "Cannot occur, because T1 would be blocked from reading T2''s uncommitted write by T2''s held exclusive lock"]'::jsonb, 3, 'dbms', 'hard', true),
('Which statement correctly describes the relationship between conflict serializability and view serializability?', '["Every view-serializable schedule is also conflict-serializable", "Conflict serializability and view serializability are exactly equivalent concepts", "Neither form of serializability implies the other in any case", "Every conflict-serializable schedule is view-serializable, but not every view-serializable schedule is conflict-serializable"]'::jsonb, 3, 'dbms', 'hard', true);
INSERT INTO question_bank (question_text, options, correct_option, topic, difficulty, is_active) VALUES
('A lock that allows multiple transactions to read a data item simultaneously, but prevents any transaction from writing to it, is called a:', '["Exclusive lock (X-lock)", "Shared lock (S-lock)", "Binary lock", "Intent lock"]'::jsonb, 1, 'dbms', 'easy', true),
('A lock that allows only one transaction to read or write a data item, blocking all other transactions from accessing it, is called a:', '["Shared lock (S-lock)", "Read lock", "Exclusive lock (X-lock)", "Latch"]'::jsonb, 2, 'dbms', 'easy', true),
('In two-phase locking (2PL), the two phases are called the growing phase and the:', '["Shrinking phase", "Waiting phase", "Locking phase", "Commit phase"]'::jsonb, 0, 'dbms', 'easy', true),
('During the growing phase of two-phase locking, a transaction:', '["May only release locks, and cannot acquire any", "May only acquire locks, and cannot release any", "May both acquire and release locks freely", "Can neither acquire nor release locks"]'::jsonb, 1, 'dbms', 'easy', true),
('During the shrinking phase of two-phase locking, a transaction:', '["May only acquire locks, and cannot release any", "May both acquire and release locks freely", "Can neither acquire nor release locks", "May only release locks, and cannot acquire any new ones"]'::jsonb, 3, 'dbms', 'easy', true),
('A situation where two or more transactions wait indefinitely for each other to release locks is called:', '["Deadlock", "Starvation", "Livelock", "Serialization failure"]'::jsonb, 0, 'dbms', 'easy', true),
('A situation where a transaction waits indefinitely because other transactions are repeatedly given priority for the same lock is called:', '["Deadlock", "Rollback", "Starvation", "Timeout"]'::jsonb, 2, 'dbms', 'easy', true),
('Which technique detects deadlocks by examining a graph in which transactions wait for resources held by other transactions?', '["A wait-for graph", "A B-tree", "A hash graph", "A lock-table graph"]'::jsonb, 0, 'dbms', 'easy', true),
('A protocol that requires every transaction to acquire all the locks it will ever need before it begins execution is known as the:', '["Two-phase locking protocol", "Timestamp ordering protocol", "Pre-claiming (conservative) locking protocol", "Optimistic concurrency control protocol"]'::jsonb, 2, 'dbms', 'easy', true),
('The simplest way to recover once a deadlock has been detected is to:', '["Wait indefinitely for the deadlock to clear itself", "Abort (roll back) one or more of the transactions involved in the deadlock", "Restart the entire database server", "Convert all held locks in the cycle to shared locks"]'::jsonb, 1, 'dbms', 'easy', true),
('Strict two-phase locking additionally requires that:', '["All locks be acquired at the very start of the transaction", "Only shared locks ever be used, never exclusive locks", "Locks be released immediately after each individual operation", "All exclusive locks held by a transaction be released only after the transaction commits or aborts"]'::jsonb, 3, 'dbms', 'medium', true),
('In timestamp-based concurrency control, each transaction is assigned a unique timestamp typically based on:', '["The transaction''s assigned priority level", "The number of locks the transaction holds", "The size of the transaction''s data set", "The time the transaction started (system clock value or a logical counter)"]'::jsonb, 3, 'dbms', 'medium', true),
('In the basic timestamp ordering protocol, if transaction T attempts to write a data item that has already been read by another transaction with a larger (later) timestamp than T, T''s write request is:', '["Always allowed to proceed unconditionally", "Rejected, and T is rolled back", "Delayed until the reader commits, without rolling back T", "Silently converted into a read operation"]'::jsonb, 1, 'dbms', 'medium', true),
('Optimistic concurrency control is based on the assumption that conflicts between transactions are:', '["Frequent, so all data must be locked upfront", "Impossible, so no conflict checking is ever needed", "Rare, so validation for conflicts is deferred to the end of the transaction instead of locking upfront", "Entirely the responsibility of the operating system"]'::jsonb, 2, 'dbms', 'medium', true),
('The three phases of optimistic concurrency control are read, validation, and:', '["Write", "Lock", "Rollback", "Commit-wait"]'::jsonb, 0, 'dbms', 'medium', true),
('Multiversion concurrency control (MVCC) mainly improves read performance by:', '["Preventing all write operations from occurring", "Letting readers access an older committed version of data without blocking on locks held by concurrent writers", "Storing only the single latest version of every data item", "Forcing all reads to use exclusive locks"]'::jsonb, 1, 'dbms', 'medium', true),
('In multiple-granularity locking, an ''intention shared'' (IS) lock on a node indicates that:', '["The entire subtree rooted at that node is exclusively locked", "No locks exist anywhere within that subtree", "The node itself is scheduled for deletion", "Shared locks are held (or will be requested) on some descendant node(s) of that node"]'::jsonb, 3, 'dbms', 'medium', true),
('Deadlock-avoidance schemes such as wait-die and wound-wait decide whether a transaction should wait or be rolled back based mainly on:', '["The relative timestamps (ages) of the transactions involved", "The number of locks each transaction currently holds", "The size of the data item being locked", "The isolation level configured for each transaction"]'::jsonb, 0, 'dbms', 'medium', true),
('In the wait-die scheme, if an OLDER transaction requests a lock currently held by a YOUNGER transaction, the older transaction:', '["Is aborted immediately", "Forces the younger transaction to abort right away", "Waits for the younger transaction to release the lock", "Is granted the lock immediately, bypassing the younger transaction"]'::jsonb, 2, 'dbms', 'medium', true),
('In the wound-wait scheme, if an OLDER transaction requests a lock currently held by a YOUNGER transaction, the younger transaction:', '["Is ''wounded'' (aborted/rolled back), and the lock is granted to the older transaction", "Continues to hold the lock while the older transaction waits", "Is automatically granted a shared lock as a compromise", "Immediately becomes the sole owner of the lock regardless of the older transaction"]'::jsonb, 0, 'dbms', 'medium', true),
('Transaction T1 holds a lock on item A and requests a lock on item B, while transaction T2 holds a lock on item B and requests a lock on item A. This situation is best resolved by:', '["Allowing both transactions to proceed simultaneously anyway", "Converting both lock requests into shared locks", "Detecting the cycle in the wait-for graph and aborting one of the transactions to break the deadlock", "Ignoring the situation, since it will resolve itself over time"]'::jsonb, 2, 'dbms', 'hard', true),
('Which statement correctly differentiates conservative (static) two-phase locking from basic two-phase locking?', '["Conservative 2PL releases locks before acquiring new ones, unlike basic 2PL", "Conservative 2PL acquires all required locks before the transaction begins execution, which prevents deadlocks, whereas basic 2PL can still deadlock", "Conservative 2PL and basic 2PL are functionally identical in every respect", "Conservative 2PL does not guarantee serializability while basic 2PL does"]'::jsonb, 1, 'dbms', 'hard', true),
('In a wait-for graph used for deadlock detection, a directed edge from Ti to Tj indicates that:', '["Ti has already acquired every lock it needs from Tj", "Tj is waiting for a lock held by Ti", "Ti and Tj are executing concurrently with no conflict between them", "Ti is waiting for a lock that is currently held by Tj"]'::jsonb, 3, 'dbms', 'hard', true),
('Under the multiversion timestamp ordering protocol, a read request from transaction Ti for data item Q is served using:', '["Always the most recently committed version, regardless of any timestamp comparison", "The version of Q with the smallest timestamp overall", "A brand-new version of Q created specifically for Ti", "The version of Q with the largest timestamp that is still less than or equal to Ti''s timestamp"]'::jsonb, 3, 'dbms', 'hard', true),
('Which of the following best explains why strict two-phase locking (Strict 2PL) guarantees both serializability and recoverability?', '["It guarantees serializability only, and has no bearing on recoverability", "It produces conflict-serializable schedules via the 2PL rule, and holding exclusive locks until commit/abort prevents other transactions from reading uncommitted data, thereby avoiding cascading rollbacks", "It guarantees recoverability only, and has no bearing on serializability", "It relates purely to deadlock prevention and has no connection to serializability"]'::jsonb, 1, 'dbms', 'hard', true);
INSERT INTO question_bank (question_text, options, correct_option, topic, difficulty, is_active) VALUES
('An index in a database is primarily used to:', '["Enforce referential integrity between tables", "Store backup copies of the data", "Speed up data retrieval operations on a table", "Encrypt sensitive column data"]'::jsonb, 2, 'dbms', 'easy', true),
('A primary index is built on a data file that is:', '["Ordered (sorted) on the indexing/search key field", "Unordered on the search key field", "Encrypted on disk", "Stored only in compressed form"]'::jsonb, 0, 'dbms', 'easy', true),
('An index built on a non-key field, which may therefore have duplicate index entries, is called a:', '["Primary index", "Secondary (non-unique) index", "Clustering index, exclusively", "Composite key index"]'::jsonb, 1, 'dbms', 'easy', true),
('A clustering index is created on a field that:', '["Must always be the primary key of the table", "Is always guaranteed to be unique", "Cannot be used to speed up range queries", "Is not necessarily a key, but determines the physical ordering of records in the file"]'::jsonb, 3, 'dbms', 'easy', true),
('Which data structure is most commonly used to implement database indexes for efficient range queries?', '["B+ tree", "Linked list", "Stack", "Hash table, exclusively"]'::jsonb, 0, 'dbms', 'easy', true),
('A view in SQL is best described as:', '["A physical copy of a table stored permanently on disk", "An index built on top of a table", "A virtual table based on the result of a stored SELECT query", "A scheduled backup of the database"]'::jsonb, 2, 'dbms', 'easy', true),
('Which SQL statement is used to create a view?', '["CREATE VIEW", "CREATE TABLE", "CREATE INDEX", "MAKE VIEW"]'::jsonb, 0, 'dbms', 'easy', true),
('A trigger in a database is:', '["A type of index used for fast lookups", "A backup mechanism that runs on a daily schedule", "A stored procedure that automatically executes in response to specific events (such as INSERT, UPDATE, or DELETE) on a table", "A hint given to the query optimizer"]'::jsonb, 2, 'dbms', 'easy', true),
('Which of the following is a valid triggering event for a standard database trigger?', '["AFTER SELECT", "AFTER UPDATE", "ON READ", "BEFORE INDEX"]'::jsonb, 1, 'dbms', 'easy', true),
('Insertion anomalies, deletion anomalies, and update anomalies are all problems primarily caused by:', '["Excessive use of indexes on a table", "Using views instead of base tables", "Overuse of triggers on a table", "Poorly normalized (redundant) relational schema design"]'::jsonb, 3, 'dbms', 'easy', true),
('Which type of index physically stores the actual data record itself (not just a pointer) at each leaf-level entry?', '["Non-clustered index", "Secondary index", "Bitmap index", "Clustered index"]'::jsonb, 3, 'dbms', 'medium', true),
('A table can have at most how many clustered indexes, in typical relational database implementations?', '["An unlimited number", "One", "Two", "Zero; only non-clustered indexes are allowed"]'::jsonb, 1, 'dbms', 'medium', true),
('A table can typically have how many non-clustered (secondary) indexes?', '["Exactly one", "None at all", "Multiple (many)", "Exactly two"]'::jsonb, 2, 'dbms', 'medium', true),
('Which type of view, when updated, directly modifies the underlying base table(s) from which it was derived?', '["An updatable view", "A materialized view snapshot that is never refreshed", "A strictly read-only view", "An indexed report"]'::jsonb, 0, 'dbms', 'medium', true),
('A materialized view differs from a regular (virtual) view in that it:', '["Is always recomputed fresh on every query with no storage involved", "Physically stores the query result on disk and must be refreshed to reflect changes in the underlying data", "Cannot be indexed under any circumstances", "Is used exclusively for DDL statements"]'::jsonb, 1, 'dbms', 'medium', true),
('Which of the following views is generally NOT updatable through standard SQL?', '["A view based on a simple single-table SELECT with no aggregation", "A view that includes all of the base table''s primary key columns", "A view with no joins and no grouping", "A view defined using GROUP BY together with aggregate functions"]'::jsonb, 3, 'dbms', 'medium', true),
('A BEFORE trigger executes:', '["Before the triggering DML statement''s changes are applied to the table", "After the triggering DML statement''s changes have been applied", "Only during execution of a SELECT statement", "Independently of any DML event, purely on a fixed schedule"]'::jsonb, 0, 'dbms', 'medium', true),
('An AFTER trigger executes:', '["Before the DML statement is even parsed", "Instead of the DML statement itself", "After the triggering DML statement''s changes have already been applied to the table", "Only when the enclosing transaction is rolled back"]'::jsonb, 2, 'dbms', 'medium', true),
('An INSTEAD OF trigger is typically used to:', '["Allow modifications through a non-updatable view by intercepting and redirecting the DML operation", "Permanently disable all other triggers", "Replace indexes with views for performance", "Automatically create scheduled backups"]'::jsonb, 0, 'dbms', 'medium', true),
('Bitmap indexes are generally most efficient for columns with:', '["High cardinality (many distinct values, such as unique IDs)", "No repeated values whatsoever", "Low cardinality (few distinct values)", "Only floating-point numeric data"]'::jsonb, 2, 'dbms', 'medium', true),
('In a B+ tree index over a table with millions of rows, why are B+ trees generally preferred over simple binary search trees for disk-based indexing?', '["B+ trees always consume less total storage than binary search trees", "B+ trees have a high fan-out (branching factor) that minimizes tree height and the number of disk I/O operations needed to locate a record", "B+ trees never require rebalancing, unlike binary search trees", "B+ trees store data pointers only in internal nodes, never in leaf nodes"]'::jsonb, 1, 'dbms', 'hard', true),
('Why do B+ tree indexes store all actual data pointers only at the leaf level, with leaf nodes linked sequentially to one another?', '["It reduces the total number of leaf nodes that are ever needed", "It removes the need for a search key value in internal nodes", "It allows the tree to remain unbalanced without any performance penalty", "It enables efficient sequential range-query scans while keeping internal nodes compact for fast traversal"]'::jsonb, 3, 'dbms', 'hard', true),
('A view is defined as: CREATE VIEW dept_avg AS SELECT dept_id, AVG(salary) AS avg_sal FROM employees GROUP BY dept_id. Which operation on this view is NOT allowed in standard SQL?', '["SELECT * FROM dept_avg WHERE avg_sal > 40000", "Using dept_avg as a table in a JOIN with another table", "Ordering the results of a SELECT issued against dept_avg", "INSERT INTO dept_avg VALUES (10, 50000)"]'::jsonb, 3, 'dbms', 'hard', true),
('Which statement about triggers and cascading effects is TRUE?', '["Triggers can never invoke other triggers under any circumstance", "A trigger can itself cause other triggers to fire (cascading), which can create complex, hard-to-debug chains if not carefully controlled", "Triggers always execute in a completely separate transaction from the triggering statement", "Triggers cannot access the OLD or NEW values of the row being modified"]'::jsonb, 1, 'dbms', 'hard', true),
('Comparing a dense index to a sparse index on a sorted data file, which statement is correct?', '["A sparse index requires more storage space than a dense index", "A dense index can only ever be built on a non-key field", "A dense index has one entry for every search-key value in the file, while a sparse index has entries for only some values, typically one per block", "A sparse index always yields faster lookups than a dense index, for every possible search"]'::jsonb, 2, 'dbms', 'hard', true);
INSERT INTO question_bank (question_text, options, correct_option, topic, difficulty, is_active) VALUES
('Which SQL command category includes the CREATE, ALTER, and DROP statements?', '["DDL (Data Definition Language)", "DML (Data Manipulation Language)", "DCL (Data Control Language)", "TCL (Transaction Control Language)"]'::jsonb, 0, 'dbms', 'easy', true),
('Which SQL command category includes the INSERT, UPDATE, and DELETE statements?', '["DDL (Data Definition Language)", "DML (Data Manipulation Language)", "DCL (Data Control Language)", "TCL (Transaction Control Language)"]'::jsonb, 1, 'dbms', 'easy', true),
('Which constraint ensures that a column cannot store duplicate values within a table?', '["CHECK constraint", "DEFAULT constraint", "FOREIGN KEY constraint", "UNIQUE constraint"]'::jsonb, 3, 'dbms', 'easy', true),
('A functional dependency X -> Y means that:', '["For any two tuples having the same value of X, their values of Y must also be the same", "X and Y must always have different values from each other", "Y functionally determines X in every case", "X and Y must both be candidate keys"]'::jsonb, 0, 'dbms', 'medium', true),
('When a referenced row in a parent table is deleted, the ON DELETE CASCADE foreign key option causes:', '["The delete operation on the parent row to be rejected outright", "The matching child rows'' foreign key values to be set to NULL instead", "All matching child rows referencing that parent row to be automatically deleted as well", "No effect whatsoever on the child table"]'::jsonb, 2, 'dbms', 'medium', true),
('The ON DELETE SET NULL referential action, when a referenced parent row is deleted, causes:', '["The foreign key column(s) in matching child rows to be set to NULL", "The matching child rows to be deleted along with the parent row", "The delete operation to be blocked entirely", "The parent row''s deletion to cascade into unrelated tables"]'::jsonb, 0, 'dbms', 'medium', true),
('Given the functional dependencies {A->B, B->C, C->A} on relation R(A,B,C), which statement about candidate keys is TRUE?', '["Only A is a candidate key of R", "R has no candidate key at all", "A, B, and C are each individually candidate keys, since each one''s closure yields all three attributes", "AB is the only candidate key of R"]'::jsonb, 2, 'dbms', 'hard', true),
('Armstrong''s axioms (reflexivity, augmentation, and transitivity) are used to:', '["Determine the physical storage layout of a database on disk", "Systematically derive all functional dependencies logically implied by a given set of functional dependencies (i.e., compute the closure)", "Optimize SQL query execution plans", "Detect deadlocks among concurrently executing transactions"]'::jsonb, 1, 'dbms', 'hard', true);
